SELECT p.supplier,i.item_code,SUM(i.qty) AS qty,SUM(i.amount) AS amount FROM "tabPurchase Invoice" p JOIN "tabPurchase Invoice Item" i ON i.parent=p.name AND i.parenttype='Purchase Invoice' WHERE p.docstatus=1 AND (%(company)s='' OR p.company=%(company)s) AND (%(from_date)s='' OR p.posting_date>=%(from_date)s) AND (%(to_date)s='' OR p.posting_date<=%(to_date)s) GROUP BY p.supplier,i.item_code ORDER BY amount DESC
